const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={length:4,mode:'unique',maxRepeat:null,difficulty:localStorage.getItem('ctc-difficulty')||'normal',pressure:false,noBs:false,coach:localStorage.getItem('ctc-coach')!=='0',effects:localStorage.getItem('ctc-effects')!=='0',battleAuto:localStorage.getItem('ctc-battle-auto')!=='0'};
let timer=null,pressureTimer=null,coachIndex=0,historyDepth=0;
const coachPrompts=['What do you know for certain after the last result?','Which digits are ruled out? Which are merely uncertain?','Can your next guess test one clear hypothesis?','If you change several digits at once, will the result be harder to interpret?','What evidence would prove your current idea wrong?'];
const fmt=sec=>{sec=Math.max(0,Math.floor(sec||0));const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`};
function applyTheme(){document.documentElement.dataset.theme=localStorage.getItem('ctc-theme')||'light'}
function applyCoach(){document.body.classList.toggle('coach-off',!state.coach);localStorage.setItem('ctc-coach',state.coach?'1':'0');if($('#coachToggle'))$('#coachToggle').textContent=`🧠 Coach: ${state.coach?'On':'Off'}`;if($('#settingsCoach'))$('#settingsCoach').checked=state.coach}
function applyNoBs(){document.body.classList.toggle('no-bs',state.noBs);if($('#noBsToggle'))$('#noBsToggle').checked=state.noBs}
function setView(id,push=true){$$('.view').forEach(v=>v.classList.add('hidden'));const el=$(`#${id}`);if(el)el.classList.remove('hidden');if(push){history.pushState({view:id},'',`#${id}`);historyDepth++}}
function showOverlay(id,push=true){$(`#${id}`)?.classList.remove('hidden');if(push){history.pushState({overlay:id},'',`#${id}`);historyDepth++}}
function hideOverlay(id){$(`#${id}`)?.classList.add('hidden')}
function closeAllOverlays(){ $$('.overlay').forEach(o=>o.classList.add('hidden'));$('#moreMenu')?.classList.add('hidden') }
function goHome(push=true){clearInterval(timer);clearInterval(pressureTimer);closeAllOverlays();setView('setup',push)}
function navigateBack(){if(historyDepth>0){history.back()}else goHome(false)}
function navigateForward(){history.forward()}
window.addEventListener('popstate',()=>{historyDepth=Math.max(0,historyDepth-1);const hash=location.hash.replace('#','');closeAllOverlays();if(hash&&document.getElementById(hash+'Overlay'))showOverlay(hash+'Overlay',false);else if(hash&&document.getElementById(hash))setView(hash,false);else setView('setup',false)});
function visibleFocusables(){return $$('button,input,select,[tabindex]:not([tabindex="-1"])').filter(el=>!el.disabled&&el.offsetParent!==null&&!el.closest('.hidden'))}
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;const els=visibleFocusables();const i=els.indexOf(document.activeElement);if(i<0)return;let n=i;if(e.key==='ArrowRight'||e.key==='ArrowDown')n=(i+1)%els.length;else n=(i-1+els.length)%els.length;e.preventDefault();els[n].focus()});
function updateSetup(){
  $$('#lengthChoices button').forEach(b=>b.classList.toggle('selected',+b.dataset.length===state.length));
  $$('#modeChoices button').forEach(b=>b.classList.toggle('selected',b.dataset.mode===state.mode));
  const ro=$('#repeatOptions');ro.classList.toggle('hidden',state.mode!=='repeat');
  if(state.mode==='repeat'){$('#repeatChoices').innerHTML=[2,3,4,5,6,7].filter(x=>x<=state.length).map(x=>`<button class="${state.maxRepeat===x?'selected':''}" data-repeat="${x}">Up to ${x}×</button>`).join('');$$('#repeatChoices button').forEach(b=>b.onclick=()=>{state.maxRepeat=+b.dataset.repeat;updateSetup()})}
  $$('#difficultyChoices button').forEach(b=>b.classList.toggle('selected',b.dataset.difficulty===state.difficulty));
}
function setMessage(x){$('#message').textContent=x||''}
function setCoach(){if($('#coachPrompt'))$('#coachPrompt').textContent=coachPrompts[coachIndex%coachPrompts.length]}
function updateRail(st){$('#railBest').textContent=st?.best??'—';$('#railWorst').textContent=st?.worst??'—';$('#railStreak').textContent=st?.current_streak??0}
async function loadStats(){const q=new URLSearchParams({length:state.length,mode:state.mode});if(state.mode==='repeat')q.set('max_repeat',state.maxRepeat);const d=await fetch('/api/stats?'+q).then(r=>r.json());updateRail(d.config||d)}
function renderSecretSlots(){const x=$('#secretSlots');x.innerHTML='';for(let i=0;i<state.length;i++){const d=document.createElement('div');d.textContent='•';x.appendChild(d)}}
function renderPositionMap(){const wrap=$('#positionMap');wrap.innerHTML='';for(let i=0;i<state.length;i++){const inp=document.createElement('input');inp.inputMode='numeric';inp.maxLength=1;inp.placeholder=String(i+1);inp.setAttribute('aria-label',`Candidate for position ${i+1}`);inp.oninput=()=>inp.value=inp.value.replace(/\D/g,'').slice(-1);wrap.appendChild(inp)}}
function updateDigitMap(){const map=$('#digitMap');map.innerHTML='';for(let d=0;d<10;d++){const b=document.createElement('button');b.textContent=d;b.dataset.state='unknown';b.setAttribute('aria-label',`Digit ${d} constraint`);b.onclick=()=>{const s=b.dataset.state;b.dataset.state=s==='unknown'?'possible':s==='possible'?'ruled':'unknown';b.className=`map-${b.dataset.state}`};map.appendChild(b)}}
function updateGuessCounter(){const v=$('#guessInput').value;$('#guessCounter').textContent=`${v.length} / ${state.length}`}
function resetGuessInput(){const i=$('#guessInput');i.value='';updateGuessCounter();i.focus()}
function validClientGuess(v){if(v.length!==state.length)return `Enter all ${state.length} digits.`;if(!/^\d+$/.test(v))return 'Digits only.';if(state.mode==='unique'&&new Set(v).size!==state.length)return 'No duplicate digits are allowed in this mode.';if(state.mode==='repeat'&&state.maxRepeat&&Math.max(...[...new Set(v)].map(d=>v.split(d).length-1))>state.maxRepeat)return `No digit can appear more than ${state.maxRepeat} times.`;return ''}
async function startGame(extra={}){
  state.pressure=extra.pressure??$('#pressureToggle').checked;state.noBs=extra.noBs??$('#noBsToggle').checked;applyNoBs();
  let timeLimit=null,attemptLimit=null;if(state.pressure){const mins=parseInt($('#pressureMinutes').value,10);const att=$('#pressureAttempts').value.trim();timeLimit=Number.isFinite(mins)&&mins>0?mins*60:null;attemptLimit=att?parseInt(att,10):null}
  const payload={length:state.length,mode:state.mode,max_repeat:state.mode==='repeat'?state.maxRepeat:null,difficulty:state.difficulty,pressure:state.pressure,time_limit:timeLimit,attempt_limit:attemptLimit,daily:!!extra.daily};
  const d=await fetch('/api/game/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(async r=>({ok:r.ok,data:await r.json()}));if(!d.ok)return setMessage(d.data.error||'Unable to start game.');
  Object.assign(state,d.data);state.startedAt=d.data.started_at;state.attempts=0;setView('game');$('#records').classList.add('hidden');$('#attemptCount').textContent='0';$('#railAttempts').textContent='0';$('#sameCount').textContent='0';$('#correctCount').textContent='0';$('#history').innerHTML='';setMessage('');renderSecretSlots();renderPositionMap();updateDigitMap();resetGuessInput();
  $('#gameModeLabel').textContent=`${state.length} DIGIT · ${state.mode==='unique'?'UNIQUE':`REPETITION · UP TO ${state.maxRepeat}×`}${state.daily?' · DAILY':''}`;$('#gameLevelLabel').textContent=state.difficulty.toUpperCase();$('#pressureBanner').classList.toggle('hidden',!state.pressure);if(state.pressure){$('#pressureBanner').textContent=`Pressure · ${state.time_limit?`time ${fmt(state.time_limit)}`:''}${state.time_limit&&state.attempt_limit?' · ':''}${state.attempt_limit?`max ${state.attempt_limit} attempts`:''}`}
  clearInterval(timer);clearInterval(pressureTimer);const tick=()=>{const elapsed=Date.now()/1000-state.startedAt;const remaining=state.pressure&&state.time_limit?Math.max(0,state.time_limit-elapsed):elapsed;$('#timer').textContent=state.pressure?fmt(remaining):fmt(elapsed);$('#railTime').textContent=state.pressure?fmt(remaining):fmt(elapsed);if(state.pressure&&state.time_limit&&remaining<=0){clearInterval(timer);clearInterval(pressureTimer);fetch('/api/game/expire',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:state.token})}).then(r=>r.json()).then(d=>{setMessage('Time limit reached.');showLossOverlay({secret:d.secret||'????',guesses_used:d.guesses_used||state.attempts,time_taken:d.elapsed||state.time_limit})})}};tick();timer=setInterval(tick,250);coachIndex=0;setCoach();
}
async function submitGuess(){const guess=$('#guessInput').value.trim();const err=validClientGuess(guess);if(err)return setMessage(err);const r=await fetch('/api/game/guess',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({guess})});const d=await r.json();if(!r.ok){if(d.pressure_lost){clearInterval(timer);clearInterval(pressureTimer);$('#message').textContent=d.error;return endPressureLoss(d)}return setMessage(d.error||'Unable to check guess.');}
  state.attempts=d.guesses_used;$('#attemptCount').textContent=d.guesses_used;$('#railAttempts').textContent=d.guesses_used;$('#sameCount').textContent=d.same;$('#correctCount').textContent=d.correct;const row=document.createElement('div');row.className='history-row';row.innerHTML=`<span>${guess}</span><b>SAME ${d.same}</b><b>CORRECT ${d.correct}</b>`;$('#history').prepend(row);setMessage(d.won?'':'Use the result to update your hypothesis.');resetGuessInput();
  if(d.pressure_lost&&!d.won){clearInterval(timer);showLossOverlay(d);return}
  if(d.won){clearInterval(timer);showWin(d)}
}
function showWin(d){$('#revealedCode').textContent=d.secret;$('#winGuesses').textContent=d.guesses_used;$('#winTime').textContent=fmt(d.time_taken);$('#recordBadge').classList.toggle('hidden',!d.new_best);$('#winMessage').textContent=`You solved it in ${d.guesses_used} guesses. Unique guesses: ${d.analysis.unique_guesses}. Efficiency: ${d.analysis.efficiency}%.`;$('#winOverlay').classList.remove('hidden');$('.win-card')?.classList.remove('win-pop');requestAnimationFrame(()=>$('.win-card')?.classList.add('win-pop'));if(state.effects)runVictoryFX()}
function showLossOverlay(d){$('#revealedCode').textContent=d.secret;$('#winGuesses').textContent=d.guesses_used||state.attempts;$('#winTime').textContent=fmt(d.time_taken);$('#recordBadge').classList.add('hidden');$('#winMessage').textContent='Pressure ended this run. Study the clues and try again.';$('#winOverlay').classList.remove('hidden');$('.win-card')?.classList.add('win-pop');}
function endPressureLoss(d){showLossOverlay({secret:d.secret||'????',guesses_used:state.attempts,time_taken:d.elapsed||0})}
function runVictoryFX(){const c=$('#fxCanvas'),ctx=c.getContext('2d');c.width=innerWidth*devicePixelRatio;c.height=innerHeight*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);const W=innerWidth,H=innerHeight,ps=[];for(let k=0;k<9;k++){setTimeout(()=>{const x=W*(.1+Math.random()*.8),y=H*(.08+Math.random()*.45);for(let i=0;i<60;i++){const a=Math.random()*Math.PI*2,s=2+Math.random()*6;ps.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:1,c:['#4263eb','#7c8cf8','#ffffff','#22a06b','#f4c95d','#d94b70'][Math.floor(Math.random()*6)],r:1+Math.random()*3})}},k*130)}const st=performance.now();function f(t){ctx.clearRect(0,0,W,H);for(let i=ps.length-1;i>=0;i--){const p=ps[i];p.x+=p.vx;p.y+=p.vy;p.vy+=.07;p.life-=.012;ctx.globalAlpha=p.life;ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();if(p.life<=0)ps.splice(i,1)}ctx.globalAlpha=1;if(t-st<4800)requestAnimationFrame(f)}requestAnimationFrame(f)}
async function showRecords(){const d=await fetch('/api/stats').then(r=>r.json());$('#statsGrid').innerHTML=[['Games',d.total],['Wins',d.wins],['Win rate',d.win_rate+'%'],['Best',d.best??'—'],['Highest',d.worst??'—'],['Average',d.average??'—'],['Fastest',d.fastest?fmt(d.fastest):'—'],['Streak',d.best_streak]].map(x=>`<div class="stat"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('');const h=await fetch('/api/game/history').then(r=>r.json());$('#recentGames').innerHTML=h.games.length?h.games.map(g=>`<div class="history-row"><span>${g.length}D · ${g.mode==='unique'?'Unique':`Repeat ${g.max_repeat}×`}${g.daily?' · Daily':''}${g.pressure?' · Pressure':''}${g.counted?'':' · archived'}</span><b>${g.guesses_used} guesses</b><b>${g.time_taken?fmt(g.time_taken):'—'}</b></div>`).join(''):'<p class="muted">No completed games yet.</p>';setView('records')}
async function loadProfiles(){const d=await fetch('/api/profile').then(r=>r.json());$('#profileList').innerHTML=d.profiles.map(p=>`<button class="profile-item ${p.id===d.active_id?'active':''}" data-id="${p.id}">👤 ${p.name}</button>`).join('');$$('.profile-item').forEach(b=>b.onclick=async()=>{await fetch('/api/profile/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:+b.dataset.id})});location.hash='';location.reload()})}
function resetLab(){lab.guesses=[];$('#labSame').textContent='—';$('#labCorrect').textContent='—';$('#labResult').textContent='';$('#labGuess').value='';}
const lab={secret:'5831',guesses:[]};
function labEval(secret,guess){let c=0,s=0;for(let i=0;i<guess.length;i++){if(secret[i]===guess[i])c++}const sc={},gc={};for(const d of secret)sc[d]=(sc[d]||0)+1;for(const d of guess)gc[d]=(gc[d]||0)+1;for(const d in gc)s+=Math.min(gc[d],sc[d]||0);return{same:s,correct:c}}
function submitLab(){const g=$('#labGuess').value.trim();if(!/^\d{4}$/.test(g))return $('#labResult').textContent='Enter exactly four digits.';const e=labEval(lab.secret,g);lab.guesses.push({g,...e});$('#labSame').textContent=e.same;$('#labCorrect').textContent=e.correct;$('#labResult').textContent=e.correct===4?`Solved the lab in ${lab.guesses.length} guesses. This does not change Records.`:`Observation ${lab.guesses.length}: SAME ${e.same}, CORRECT ${e.correct}. Ask what this result rules in or out.`}
// Battle
const battle={};
function bGen(len,mode,lim){const d='0123456789';if(mode==='unique'){return [...d].sort(()=>Math.random()-.5).slice(0,len).join('')}while(true){let s='';for(let i=0;i<len;i++)s+=d[Math.floor(Math.random()*10)];if(Math.max(...[...new Set(s)].map(x=>s.split(x).length-1))<=lim)return s}}
function bEval(secret,guess){const correct=[...secret].reduce((n,x,i)=>n+(x===guess[i]?1:0),0);const sc={},gc={};for(const x of secret)sc[x]=(sc[x]||0)+1;for(const x of guess)gc[x]=(gc[x]||0)+1;let same=0;for(const x in gc)same+=Math.min(gc[x],sc[x]||0);return{same,correct}}
function bValid(s){if(!/^\d+$/.test(s)||s.length!==battle.len)return false;if(battle.mode==='unique'&&new Set(s).size!==battle.len)return false;if(battle.mode==='repeat'&&Math.max(...[...new Set(s)].map(x=>s.split(x).length-1))>battle.lim)return false;return true}
function candidatePool(){const out=new Set(),target=battle.len<=5?30000:10000;let guard=0;while(out.size<target&&guard<target*8){out.add(bGen(battle.len,battle.mode,battle.lim));guard++}return [...out]}
function robotPick(){let c=battle.candidates.filter(x=>battle.robotEvidence.every(e=>{const r=bEval(e.guess,x);return r.same===e.same&&r.correct===e.correct}));if(c.length)battle.candidates=c;const pool=battle.candidates;if(battle.diff==='relaxed')return bGen(battle.len,battle.mode,battle.lim);if(battle.diff==='easy')return pool[Math.floor(Math.random()*pool.length)];if(battle.diff==='normal')return pool[Math.floor(pool.length/2)];const sample=battle.diff==='extreme'?Math.min(120,pool.length):Math.min(45,pool.length);let best=pool[0],bestScore=Infinity;for(let i=0;i<sample;i++){const g=pool[i],b={};for(const cnd of pool){const e=bEval(g,cnd),k=e.same+','+e.correct;b[k]=(b[k]||0)+1}const worst=Math.max(...Object.values(b));if(worst<bestScore){bestScore=worst;best=g}}return best}
function battleLog(text){const x=document.createElement('div');x.className='history-row';x.innerHTML=text;$('#battleLog').prepend(x)}
function updateBattleMasks(){const m='• '.repeat(battle.len).trim();$('#yourSecretMask').textContent=m;$('#robotSecretMask').textContent=m}
function startBattle(){battle.len=+$('#battleLength').value;battle.mode=$('#battleMode').value;battle.lim=battle.mode==='repeat'?Math.min(+$(`#battleRepeat`).value,battle.len):null;battle.diff=$('#battleDifficulty').value;battle.auto=$('#battleAuto').checked;const yours=$('#yourBattleSecret').value.trim();if(!bValid(yours))return alert('Enter a valid secret for this configuration.');battle.yourSecret=yours;battle.robotSecret=bGen(battle.len,battle.mode,battle.lim);battle.robotEvidence=[];battle.yourGuesses=[];battle.robotGuesses=[];battle.candidates=candidatePool();battle.round=1;battle.done=false;$('#battleSetupOverlay').classList.add('hidden');$('#battleOverlay').classList.remove('hidden');history.pushState({overlay:'battleOverlay'},'', '#battleOverlay');historyDepth++;$('#battleLevelPill').textContent=battle.diff.toUpperCase();$('#battleAutoState').textContent=battle.auto?'AUTO ON':'AUTO OFF';$('#battleRound').textContent='ROUND 1';updateBattleMasks();$('#battleLog').innerHTML='';showRobotTurn()}
function showRobotTurn(){if(battle.done)return;battle.turn='robot';$('#battleTurnTitle').textContent='🤖 Robot’s turn';$('#humanTurn').classList.add('hidden');$('#robotFeedbackForm').classList.toggle('hidden',battle.auto);$('#battleGuessLabel').textContent='ROBOT GUESS';const g=robotPick();battle.pendingRobotGuess=g;$('#battleGuess').textContent=g;$('#battleStatus').textContent=battle.auto?'Auto Feedback will evaluate this guess…':'Give the robot the feedback it earned.';$('#battleSame').textContent='—';$('#battleCorrect').textContent='—';if(battle.auto)setTimeout(()=>applyRobotFeedback(bEval(battle.yourSecret,g)),500)}
function applyRobotFeedback(e){battle.robotEvidence.push({guess:battle.pendingRobotGuess,...e});battle.robotGuesses.push(battle.pendingRobotGuess);battleLog(`<span>🤖 ${battle.pendingRobotGuess}</span><b>SAME ${e.same}</b><b>CORRECT ${e.correct}</b>`);$('#battleSame').textContent=e.same;$('#battleCorrect').textContent=e.correct;$('#robotSameInput').value='';$('#robotCorrectInput').value='';if(e.correct===battle.len){battle.done=true;$('#battleStatus').textContent=`Robot cracked your code in ${battle.robotGuesses.length} guesses.`;$('#battleTurnTitle').textContent='🤖 Robot wins';$('#robotFeedbackForm').classList.add('hidden');return}showHumanTurn()}
function showHumanTurn(){battle.turn='human';$('#battleTurnTitle').textContent='🧠 Your turn';$('#humanTurn').classList.remove('hidden');$('#robotFeedbackForm').classList.add('hidden');$('#battleGuessLabel').textContent='YOUR GUESS';$('#battleGuess').textContent='YOUR TURN';$('#battleStatus').textContent='Guess the robot’s secret.';$('#battleSame').textContent='—';$('#battleCorrect').textContent='—';$('#humanBattleGuess').value='';$('#humanBattleGuess').maxLength=battle.len;$('#humanBattleGuess').focus();$('#battleRound').textContent=`ROUND ${battle.round}`}
function submitRobotFeedback(){const s=+$('#robotSameInput').value,c=+$('#robotCorrectInput').value;if(!Number.isInteger(s)||!Number.isInteger(c)||s<0||c<0||c>s||s>battle.len||c>battle.len)return alert('Feedback must be valid counts.');applyRobotFeedback({same:s,correct:c})}
function submitHumanGuess(){const g=$('#humanBattleGuess').value.trim();if(!bValid(g))return alert('Enter a valid guess.');const e=bEval(battle.robotSecret,g);battle.yourGuesses.push({guess:g,...e});battleLog(`<span>🧠 ${g}</span><b>SAME ${e.same}</b><b>CORRECT ${e.correct}</b>`);$('#battleSame').textContent=e.same;$('#battleCorrect').textContent=e.correct;if(e.correct===battle.len){battle.done=true;$('#battleStatus').textContent=`You cracked the robot in ${battle.yourGuesses.length} guesses!`;$('#battleTurnTitle').textContent='🧠 You win';$('#humanTurn').classList.add('hidden');return}battle.round++;showRobotTurn()}
function closeBattle(){battle.done=true;hideOverlay('battleOverlay')}

// ===== V7 TWO PLAYER MULTIPLAYER =====
const mp={ws:null,room:null,slot:null,code:null,clientId:localStorage.getItem('ctc-v7-client')||crypto.randomUUID(),server:localStorage.getItem('ctc-v7-server')||location.origin.replace(/^http/,'ws')+'/ws'};
localStorage.setItem('ctc-v7-client',mp.clientId);
function mpSetConnection(ok,text){$('#mpConnectionDot').style.color=ok?'var(--green)':'var(--danger)';$('#mpConnectionText').textContent=text}
function mpConnect(){
  if(mp.ws && [0,1].includes(mp.ws.readyState)) return;
  try{mp.ws=new WebSocket(mp.server)}catch(e){mpSetConnection(false,'Invalid server URL');return}
  mp.ws.onopen=()=>{mpSetConnection(true,'Connected');const rc=localStorage.getItem('ctc-v7-room');if(rc)mpSend({type:'resume',code:rc,client_id:mp.clientId})};
  mp.ws.onclose=()=>mpSetConnection(false,'Disconnected');
  mp.ws.onerror=()=>mpSetConnection(false,'Connection error');
  mp.ws.onmessage=e=>{let d;try{d=JSON.parse(e.data)}catch{return}mpHandle(d)}
}
function mpSend(d){
  mpConnect();
  const send=()=>{if(mp.ws&&mp.ws.readyState===1)mp.ws.send(JSON.stringify(d));else setTimeout(send,100)};
  send();
}
function mpSettingsFromUI(){return{length:+$('#mpLength').value,mode:$('#mpMode').value,max_repeat:$('#mpMode').value==='repeat'?+$('#mpRepeat').value:null,difficulty:$('#mpDifficulty').value,feedback_mode:$('#mpFeedback').value,pressure:$('#mpPressure').checked,time_limit:$('#mpPressure').checked?+$('#mpTime').value:null,attempt_limit:$('#mpPressure').checked&&$('#mpAttempts').value?+$('#mpAttempts').value:null}}
function mpRenderSettings(s){
  $('#mpLength').value=s.length;$('#mpMode').value=s.mode;$('#mpRepeat').value=s.max_repeat||2;$('#mpDifficulty').value=s.difficulty;$('#mpFeedback').value=s.feedback_mode;$('#mpPressure').checked=!!s.pressure;$('#mpTime').value=s.time_limit||5;$('#mpAttempts').value=s.attempt_limit||'';$('#mpRepeatWrap').classList.toggle('hidden',s.mode!=='repeat');$('#mpPressureWrap').classList.toggle('hidden',!s.pressure);
  $('#mpGameModeLabel').textContent=s.feedback_mode==='automatic'?'AUTOMATIC':'MANUAL';$('#mpFeedbackLabel').textContent=s.feedback_mode==='automatic'?'AUTO':'MANUAL';
  $('#mpSecretInput').maxLength=s.length;$('#mpGuessInput').maxLength=s.length;$('#mpSecretInput').placeholder='Enter '+s.length+' digits';$('#mpGuessInput').placeholder='Enter '+s.length+' digits';$('#mpSecretLength').textContent=s.length+' DIGITS';$('#mpSecretHint').textContent='Enter your private '+s.length+'-digit secret. It is stored only on the game server and never sent to your opponent.';
}
function mpRenderGuestSettings(s){$('#mpGuestSettingsText').innerHTML=`<b>${s.length} digits · ${s.mode==='unique'?'Unique':'Repetition'} · ${s.difficulty[0].toUpperCase()+s.difficulty.slice(1)} · ${s.feedback_mode==='automatic'?'Automatic feedback':'Manual feedback'}</b>${s.pressure?`<br><small>Pressure: ${s.time_limit?s.time_limit+' min':''}${s.attempt_limit?` · ${s.attempt_limit} attempts`:''}</small>`:''}`}
function mpHandle(d){
  if(d.type==='error'){alert(d.message);return}
  if(d.type==='joined'){mp.code=d.code;mp.slot=d.slot;mp.room=d.room;localStorage.setItem('ctc-v7-room',d.code);$('#mpJoinCode').value=d.code;hideOverlay('twoPlayerSetupOverlay');showOverlay('mpRoomOverlay');mpRenderRoom();return}
  if(d.type==='state'){mp.room=d.room;mp.slot=d.you;mpRenderRoom();if(d.room.status==='playing'||d.room.status==='finished'){hideOverlay('mpRoomOverlay');showOverlay('mpGameOverlay');mpRenderGame()};return}
  if(d.type==='turn'){mp.room&&(mp.room.turn=d.slot);mpRenderGame()}
}
function mpRenderRoom(){
  const r=mp.room,s=r.settings;
  $('#mpRoomCode').textContent=r.code;$('#mpP1Name').textContent=r.players[0].name;$('#mpP2Name').textContent=r.players[1].name;
  $('#mpP1State').textContent=r.players[0].ready?'✓ Secret locked':'Waiting for secret';$('#mpP2State').textContent=r.players[1].ready?'✓ Secret locked':'Waiting for secret';
  const host=mp.slot===1;$('#mpHostSettings').classList.toggle('hidden',!host);$('#mpGuestSettings').classList.toggle('hidden',host);if(host)mpRenderSettings(s);else mpRenderGuestSettings(s);
  $('#mpSecretInput').disabled=r.status!=='lobby'||(mp.slot===1?r.players[0].ready:r.players[1].ready);$('#mpSecretBtn').disabled=$('#mpSecretInput').disabled;
  if(r.status==='lobby')$('#mpTurnBanner').textContent=(r.players[0].ready&&r.players[1].ready)?'Starting…':'Both players: enter your private secret.';
  else $('#mpTurnBanner').textContent='Game started — turns are one at a time.';
}
function mpRenderHistory(){
  const h=mp.room?.history||[];$('#mpHistory').innerHTML=h.length?h.map(x=>`<div class="mp-history-entry"><div class="row"><b>${x.name}</b><small>Round ${x.round}</small></div><div class="row"><span><strong>${x.guess}</strong></span><span><b>SAME ${x.same}</b><b>CORRECT ${x.correct}</b></span></div></div>`).join(''):'<div class="muted">No guesses yet.</div>';
  $('#mpHistory').scrollTop=$('#mpHistory').scrollHeight;
}
function mpRenderGame(){
  if(!mp.room)return;const r=mp.room,s=r.settings,me=mp.slot,target=me===1?2:1;
  $('#mpRoundLabel').textContent=`ROUND ${(r.history?.length||0)+1}`;$('#mpTargetName').textContent=r.players[target-1].name;
  $('#mpTargetMask').textContent=Array(s.length).fill('●').join(' ');
  const myTurn=r.status==='playing'&&r.turn===me&&!r.pending;$('#mpMyTurnLabel').textContent=myTurn?'YOUR TURN':'WAITING';
  $('#mpGuessArea').classList.toggle('hidden',!myTurn);$('#mpWaitingArea').classList.toggle('hidden',myTurn||r.status!=='playing'||!!r.pending);
  const pending=r.pending;const needFeedback=!!pending&&pending.target===me;
  $('#mpPendingFeedback').classList.toggle('hidden',!needFeedback);
  if(needFeedback){$('#mpPendingGuesser').textContent=r.players[pending.slot-1].name;$('#mpPendingGuess').textContent=pending.guess}
  const waitingFeedback=!!pending&&pending.slot===me; if(waitingFeedback)$('#mpWaitingArea').classList.remove('hidden');
  const last=r.history?.[r.history.length-1];$('#mpLatestResult').classList.toggle('hidden',!last);if(last){$('#mpLatestGuess').textContent=last.guess;$('#mpLatestSame').textContent=last.same;$('#mpLatestCorrect').textContent=last.correct}
  $('#mpGameMessage').textContent=r.status==='finished'?`Winner: ${r.players[r.winner-1].name}.`:pending?'Manual verification is required.':myTurn?'Your move.':'Waiting for the other player…';
  mpRenderHistory();
  $('#mpWinner').classList.toggle('hidden',r.status!=='finished');if(r.status==='finished'){const win=r.winner===me;$('#mpWinnerTitle').textContent=win?'You cracked it! 🏆':`${r.players[r.winner-1].name} cracked it!`;$('#mpWinnerText').textContent=win?'Your guess reached the full CORRECT count.':`The winning guess was made by ${r.players[r.winner-1].name}.`}
}
function mpCreate(){
  const name=$('#mpCreateName').value.trim()||'Player 1';mpConnect();mpSend({type:'create',name,settings:mpSettingsFromUI(),client_id:mp.clientId})
}
function mpJoin(){
  const code=$('#mpJoinCode').value.trim().toUpperCase();if(code.length!==6)return alert('Enter the 6-character room code.');const name=$('#mpJoinName').value.trim()||'Player 2';mpConnect();mpSend({type:'join',code,name,client_id:mp.clientId})
}
function mpApplySettings(){const s=mpSettingsFromUI();mpSend({type:'settings',settings:s});$('#mpSecretInput').value='';$('#mpSecretStatus').textContent='Settings applied. Enter your new '+s.length+'-digit secret.';mpRenderSettings(s)}
function mpLockSecret(){
  const v=$('#mpSecretInput').value.trim();if(!mp.room)return;if(!/^\d+$/.test(v)||v.length!==mp.room.settings.length)return alert(`Enter exactly ${mp.room.settings.length} digits.`);mpSend({type:'secret',secret:v});$('#mpSecretStatus').textContent='Secret sent securely to the server.'}
function mpGuess(){
  const v=$('#mpGuessInput').value.trim();if(!mp.room)return;if(!/^\d+$/.test(v)||v.length!==mp.room.settings.length)return alert(`Enter exactly ${mp.room.settings.length} digits.`);mpSend({type:'guess',guess:v});$('#mpGuessInput').value=''}
function mpManualSubmit(){const same=+$('#mpManualSame').value,correct=+$('#mpManualCorrect').value;if(!Number.isInteger(same)||!Number.isInteger(correct)||same<0||correct<0||correct>same||same>mp.room.settings.length)return alert('Enter valid SAME/CORRECT counts.');mpSend({type:'feedback',same,correct});$('#mpManualSame').value='';$('#mpManualCorrect').value=''}
function mpLeave(){localStorage.removeItem('ctc-v7-room');mpSend({type:'leave'});if(mp.ws){mp.ws.close();mp.ws=null}mp.room=null;mp.slot=null;hideOverlay('mpRoomOverlay');hideOverlay('mpGameOverlay');showOverlay('twoPlayerSetupOverlay');mpSetConnection(false,'Not connected')}
function mpCopy(){const url=new URL(location.href);url.hash='twoPlayer';url.searchParams.set('room',mp.code);navigator.clipboard?.writeText(url.toString());$('#mpCopyRoomBtn').textContent='Copied ✓';setTimeout(()=>$('#mpCopyRoomBtn').textContent='Copy link',1200)}
$('#twoPlayerBtn').onclick=()=>{mpConnect();showOverlay('twoPlayerSetupOverlay')};$('#mpCreateBtn').onclick=mpCreate;$('#mpJoinBtn').onclick=mpJoin;$('#mpApplySettings').onclick=mpApplySettings;$('#mpSecretBtn').onclick=mpLockSecret;$('#mpGuessBtn').onclick=mpGuess;$('#mpManualSubmit').onclick=mpManualSubmit;$('#mpLeaveBtn').onclick=mpLeave;$('#mpGameLeaveBtn').onclick=mpLeave;$('#mpCopyRoomBtn').onclick=mpCopy;
$('#mpMode').onchange=()=>$('#mpRepeatWrap').classList.toggle('hidden',$('#mpMode').value!=='repeat');$('#mpPressure').onchange=()=>$('#mpPressureWrap').classList.toggle('hidden',!$('#mpPressure').checked);
